const entries=new Map();let panel=null,selectedId=null,lastTile=null;
function ensurePanel(){if(panel)return;const style=document.createElement('style');style.textContent='.moon-actions{position:fixed;bottom:88px;left:50%;transform:translateX(-50%);z-index:15;display:flex;align-items:center;gap:6px;max-width:calc(100vw - 24px);font:12px Manrope,sans-serif;flex-wrap:wrap;justify-content:center}.moon-actions[hidden]{display:none}.moon-actions button,.moon-actions select,.moon-actions output{border:1px solid var(--app-border,#c6bda7);border-radius:99px;padding:9px 12px;background:var(--app-paper,#fff9ed);color:var(--app-ink,#443d31);font:inherit;max-width:100%}.moon-actions button{cursor:pointer}.moon-actions button[data-action=vip]{background:var(--app-accent,#b64932);color:var(--app-on-accent,#fff)}.moon-actions button:disabled{opacity:.65;cursor:default}.moon-actions output{font-size:11px;flex-basis:100%;text-align:center;white-space:normal}@media(max-width:600px){.moon-actions{bottom:84px;gap:4px;width:calc(100vw - 24px)}.moon-actions button,.moon-actions select{padding:8px;font-size:11px}.moon-actions button{flex:1 1 42%;min-height:36px}.moon-actions select{flex:1 1 100%}.moon-actions output{font-size:10px;padding:5px 8px}}';document.head.append(style);panel=document.createElement('div');panel.className='moon-actions';panel.setAttribute('aria-label','Moonbase flight controls');panel.innerHTML='<select aria-label="VIP destination Moonbase"></select><button type="button" data-action="vip">Call our VIP ship</button><button type="button" data-action="supply">Request supplies</button><button type="button" data-action="follow">Follow VIPs</button><button type="button" data-action="interior">Show interior</button><output aria-live="polite"></output>';document.body.append(panel);panel.querySelector('select').onchange=e=>{selectedId=e.target.value;render();};}
function render(){ensurePanel();const family=document.body.dataset.family,eligible=[...entries.values()].filter(e=>family==='moon'?!e.embedded:family==='ranch'&&e.embedded);panel.hidden=!eligible.length;if(!eligible.length)return;const tile=document.querySelector('canvas[data-selected-tile]')?.dataset.selectedTile;if(tile!==lastTile&&eligible.some(e=>e.id===tile))selectedId=tile;lastTile=tile;const entry=eligible.find(e=>e.id===selectedId)||eligible.at(-1);selectedId=entry.id;const select=panel.querySelector('select'),signature=eligible.map(e=>e.id+e.label).join('|');if(select.dataset.signature!==signature){select.replaceChildren(...eligible.map(e=>{const o=document.createElement('option');o.value=e.id;o.textContent=e.label;return o;}));select.dataset.signature=signature;}select.value=entry.id;select.hidden=eligible.length<2;const sim=entry.getSimulation(),v=sim.state.rocket.vip,a=sim.vipAvailability(),vipButton=panel.querySelector('[data-action=vip]'),supply=panel.querySelector('[data-action=supply]'),inside=panel.querySelector('[data-action=interior]');vipButton.disabled=!a.ready;vipButton.textContent=a.ready?'Call our VIP ship':v&&v.phase!=='home'?'VIP visit underway':'VIP pad needs 80 m';vipButton.title=a.ready?'Arrive in spacesuits, celebrate, tour the base and return home. Regular ferry delayed 7 in-game days.':a.label;vipButton.onclick=()=>{if(sim.requestVip()){entry.refresh?.();document.dispatchEvent(new CustomEvent('moon-vip-state-changed',{detail:{resume:true,destination:entry.id}}));}render();};const availability=sim.dispatchAvailability();supply.disabled=!availability.ready;supply.textContent='Request supplies';supply.title=availability.label;supply.onclick=()=>{sim.requestDropship();document.dispatchEvent(new CustomEvent('moon-vip-state-changed'));render();};const follow=panel.querySelector('[data-action=follow]');follow.disabled=!v||['home','waiting-for-pad'].includes(v.phase);follow.onclick=()=>document.dispatchEvent(new CustomEvent('moon-vip-focus',{detail:{destination:entry.id}}));inside.hidden=!entry.interior?.interiorAvailable;inside.disabled=!entry.interior?.interiorDocked;inside.textContent=entry.interior?.interiorOpen?'Close hull':'Show interior';inside.setAttribute('aria-pressed',String(!!entry.interior?.interiorOpen));inside.onclick=()=>{entry.interior.setInterior(!entry.interior.interiorOpen);render();};const s=sim.state.rocket.schedule,active=v&&v.phase!=='home',status=active?`${v.phase.replaceAll('-',' ')} · You + companion + 3 retinue`:v?.returnedHome?'VIP party returned home':'Your VIP party is at home';panel.querySelector('output').textContent=`${status} · Regular ferry ${s.holding?'holding for VIP departure':`in ${Math.ceil(Math.max(0,s.nextArrival-sim.state.seconds)/6)} days`}${s.lastDelay?' · postponed 7 days':''}`;}
export function createMoonActions(getSimulation,{interior,id,label,embedded=false,refresh}={}){const token=Symbol(),entry={getSimulation,interior,id:id||'standalone-'+String(entries.size),label:label||'Moonbase',embedded,refresh};entries.set(token,entry);return {update:render,dispose(){entries.delete(token);render();}};}
